// Get image URL for a track (returns null if no image available)
export async function getTrackImageUrl(trackId) {
  const file = trackImages[trackId];
  if (file) {
    try {
      return await file.url();
    } catch (e) {
      return null;
    }
  }
  return null;
}

// Export the map for bulk access
export {trackImages};
